INSERT INTO "geo_diagnosis_brands" ("id", "name", "domain", "industry", "metadata_json", "created_at", "updated_at") VALUES ('6e271c0c-95eb-4bd7-9333-b012ecedb143', '董逻辑 MGEO', 'dongluoji.com', 'B2B SaaS', '{"evidence": "品牌资料：**董逻辑 MGEO**\n\n*   **主营业务**：董逻辑 MGEO 是一家专注于生成式引擎优化（GEO）领域的B2B SaaS服务商。其核心业务围绕企业在人工智能搜索与回答场景中的可见性与影响力展开，具体服务包括：对品牌在AI回答中的表现进行检测与诊断（品牌AI检测、TCA诊断），通过优化内容与数据策略提升AI提及率与正面性（GEO优化），并提供跨平台的内容分发与AI回答实时监测服务。\n*   **目标客户**：该品牌主要面向重视线上品牌声誉与数字营销效果的企业客户，特别是那些在激烈市场竞争中，需要确保其品牌信息在主流AI搜索与对话平台（如各类AI助手）中能被准确、积极呈现的中大型企业。目标行业可能包括消费品牌、科技公司、专业服务机构等。\n*   **核心优势**：其核心优势在于专注于“生成式AI搜索”这一新兴且快速演变的赛道，相较于传统SEO公司，它更专注于优化针对大语言模型的内容与数据。通过提供从监测、诊断到优化、分发的全链路工具，旨在帮助客户在由AI主导的信息分发环境中建立数据驱动的、可追踪的品牌影响力。其服务具有实时性和针对性强的特点，以应对AI回答动态更新的挑战。\n\n（注：以上信息基于官网披露的服务项目及行业通用知识推断而成，旨在提供客观概述。）\n核心服务：品牌AI检测, GEO优化, TCA诊断, 内容分发, AI监测\n主要竞品：Profound, Athena, Goodie, 传统SEO公司\n品牌定位：GEO监测"}', '2026-05-24 21:53:56.179461', '2026-05-25 11:34:27.243373');
INSERT INTO "geo_diagnosis_brands" ("id", "name", "domain", "industry", "metadata_json", "created_at", "updated_at") VALUES ('a3d4f706-4ee4-40a8-b263-ba21fd3ca954', '喜茶', 'heytea.com', '餐饮 / 新茶饮', '{"evidence": "品牌资料：**喜茶**是中国新茶饮行业头部品牌，主营现制茶饮，产品线涵盖水果茶、芝士茶、咖啡及烘焙甜点等。目标客户以都市年轻消费者为主，注重品牌潮流感与社交体验。其核心优势在于持续的产品创新能力、成熟的供应链管理及通过跨界联名等方式构建的品牌文化影响力。目前，喜茶在高端现制茶饮市场占据重要地位，与奈雪的茶、霸王茶姬等品牌形成直接竞争。\n核心服务：现制茶饮, 水果茶, 芝士茶, 咖啡, 烘焙甜点\n主要竞品：奈雪的茶, 茶百道, 古茗, 沪上阿姨, 霸王茶姬\n品牌定位：喜茶的品牌定位是以年轻消费者为核心，以“灵感之茶”为品牌理念，通过高品质原料、创新茶饮产品和潮流化传播，打造具有社交属性和生活方式感的新式茶饮品牌。"}', '2026-05-27 01:57:28.289084', '2026-05-27 02:18:37.111051');

