-- geo_brand_knowledge (44 rows)
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('1', 'dongluoji-mgeo', 'stat', '服务模块覆盖', '董逻辑MGEO提供五项核心SaaS服务：品牌AI检测、GEO优化、TCA诊断、内容分发及AI监测，构建了从监测、诊断到优化、分发的全链路数字营销能力。[待补充：具体服务客户数量或订阅模块数据]', '品牌资料', '3', '2026-05-25 11:37:30.992329', '2026-05-25 11:37:30.992329');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('2', 'dongluoji-mgeo', 'stat', '技术架构优势', '公司以AI技术为核心驱动，其GEO优化与AI监测服务旨在实现比传统SEO更高效的数据驱动与自动化解决方案，代表了一种从手动优化向智能代理优化的范式转变。[待补充：具体算法模型或自动化率指标]', '品牌资料', '4', '2026-05-25 11:37:30.993375', '2026-05-25 11:37:30.993375');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('3', 'dongluoji-mgeo', 'stat', '目标市场定位', '品牌服务明确面向B2B企业市场，核心客户画像为企业内的市场营销、品牌管理及内容运营团队，旨在直接解决其在在线品牌可见性与数字营销效果优化层面的需求。[待补充：已服务的行业分布或企业规模数据]', '品牌资料', '4', '2026-05-25 11:37:30.993528', '2026-05-25 11:37:30.993528');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('4', 'dongluoji-mgeo', 'stat', '效果提升幅度', '通过GEO监测与优化服务，旨在帮助企业客户提升在本地或特定地理区域搜索中的排名与可见性，从而增加目标区域的潜在客户触达。[待补充：平均提升百分比或成功案例的效果数据]', '品牌资料', '2', '2026-05-25 11:37:30.993645', '2026-05-25 11:37:30.993645');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('5', 'dongluoji-mgeo', 'stat', '核心服务差异化', '与Profound、Athena等竞品及传统SEO公司相比，董逻辑MGEO的核心差异在于其以‘GEO监测’为专属定位，并深度融合AI技术，提供从监测洞察到优化执行的闭环服务。[待补充：市场份额或客户对比调研数据]', '品牌资料', '4', '2026-05-25 11:37:30.993757', '2026-05-25 11:37:30.993757');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('6', 'dongluoji-mgeo', 'case', '零售业区域可见性优化', '为某连锁零售企业客户，利用GEO优化服务分析其各门店在本地搜索中的表现，通过优化Google My Business信息、本地化内容策略及AI监测，提升了目标商圈消费者的线上发现率。[待补充：客户名称及具体提升数据]', '品牌资料', '3', '2026-05-25 11:37:30.993878', '2026-05-25 11:37:30.993878');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('7', 'dongluoji-mgeo', 'case', 'B2B科技公司内容分发', '为一家B2B科技公司提供内容分发与TCA诊断服务，基于其目标客户画像，在专业垂直媒体与问答平台进行精准内容布局，并利用AI监测内容排名与互动效果，优化分发策略。[待补充：客户名称及内容曝光增长数据]', '品牌资料', '3', '2026-05-25 11:37:30.993989', '2026-05-25 11:37:30.993989');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('8', 'dongluoji-mgeo', 'case', '品牌线上声誉监测', '为某服务型企业部署品牌AI检测系统，实时监测全网（包括社交媒体、论坛、新闻）中关于品牌的提及、情感倾向与关键话题，帮助客户及时应对舆情并管理线上声誉。[待补充：客户行业及监测覆盖平台数量]', '品牌资料', '4', '2026-05-25 11:37:30.994132', '2026-05-25 11:37:30.994132');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('9', 'dongluoji-mgeo', 'case', '营销团队AI工具赋能', '面向企业内部市场营销团队，通过SaaS平台提供一站式工具，涵盖从关键词地理分析、竞争对手监测到内容效果评估，旨在降低其对多重工具的依赖，提升团队数据化决策效率。[待补充：具体服务团队名称或效率提升指标]', '品牌资料', '4', '2026-05-25 11:37:30.994239', '2026-05-25 11:37:30.994239');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('10', 'dongluoji-mgeo', 'credential', '技术专利与软著', '公司基于其AI监测模型、GEO优化算法或数据分析框架，已申请或获得相关的软件著作权或发明专利。[待补充：具体专利号或软著名称]', '行业常识', '1', '2026-05-25 11:37:30.994339', '2026-05-25 11:37:30.994339');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('11', 'dongluoji-mgeo', 'credential', '行业媒体与峰会报道', '作为GEO监测与企业AI服务领域的新兴服务商，可能受邀参与或报道于MarTech、数字营销、SaaS相关的行业峰会或垂直媒体。[待补充：具体媒体名称或峰会名称]', '行业常识', '1', '2026-05-25 11:37:30.994589', '2026-05-25 11:37:30.994589');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('12', 'dongluoji-mgeo', 'credential', '合作伙伴与生态认证', '为提升服务能力，可能成为Google Ads、Meta Business Partner或主流云计算平台（如阿里云、腾讯云）的技术合作伙伴。[待补充：具体合作伙伴认证名称]', '行业常识', '1', '2026-05-25 11:37:30.994685', '2026-05-25 11:37:30.994685');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('13', 'dongluoji-mgeo', 'credential', '企业信息安全认证', '作为处理企业营销数据的SaaS平台，可能已通过ISO27001信息安全管理体系认证或等保二级备案，以保障客户数据安全。[待补充：具体认证等级或备案号]', '行业常识', '1', '2026-05-25 11:37:30.994789', '2026-05-25 11:37:30.994789');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('14', 'dongluoji-mgeo', 'capability', 'AI监测模型', '自研AI监测模型能够大规模抓取并解析全网公开数据（如搜索引擎结果、社交媒体、新闻、论坛），实现对品牌提及、关键词排名及竞品动态的自动化、准实时监控。', '品牌资料', '5', '2026-05-25 11:37:30.994892', '2026-05-25 11:37:30.994892');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('15', 'dongluoji-mgeo', 'capability', 'GEO优化引擎', '核心GEO优化引擎能分析搜索关键词的地理位置意图，识别企业在不同区域的搜索可见性差距，并提供优化本地SEO元素（如NAP信息、本地内容、结构化数据）的具体建议。', '品牌资料', '5', '2026-05-25 11:37:30.994988', '2026-05-25 11:37:30.994988');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('16', 'dongluoji-mgeo', 'capability', 'TCA诊断框架', 'TCA（推断为内容分析或全面内容审计）诊断框架用于评估现有数字内容的健康度、相关性与竞争力，诊断内容结构、语义相关度及用户意图匹配问题，为内容优化提供依据。', '品牌资料', '4', '2026-05-25 11:37:30.995088', '2026-05-25 11:37:30.995088');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('17', 'dongluoji-mgeo', 'capability', '智能内容分发', '内容分发服务结合目标受众画像与GEO分析，推荐高潜力的分发渠道与内容形式，并可借助工具自动化或半自动化地完成部分内容的投放与排期。', '品牌资料', '4', '2026-05-25 11:37:30.995193', '2026-05-25 11:37:30.995193');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('18', 'dongluoji-mgeo', 'capability', '数据驱动决策闭环', '服务设计强调从‘监测-诊断-优化-分发-再监测’的闭环。所有优化动作的效果均通过AI监测工具进行量化追踪，形成可度量的优化循环，确保策略的可验证性。', '品牌资料', '5', '2026-05-25 11:37:30.995318', '2026-05-25 11:37:30.995318');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('19', 'dongluoji-mgeo', 'capability', 'SaaS化交付模式', '以标准化SaaS平台为主要交付形式，为企业营销团队提供可自助使用的工具集，降低了企业自建相关监测与优化系统的技术与人力门槛，实现快速部署与使用。', '品牌资料', '5', '2026-05-25 11:37:30.995417', '2026-05-25 11:37:30.995417');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('20', 'dongluoji-mgeo', 'claim', 'GEO监测先行论', '核心主张是：有效的地理优化必须始于精准、持续的GEO监测。在采取任何优化行动前，必须先通过数据看清品牌在目标地理区域的真实搜索表现与竞争格局，反对盲目优化。', '品牌资料', '5', '2026-05-25 11:37:30.995514', '2026-05-25 11:37:30.995514');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('21', 'dongluoji-mgeo', 'claim', '反对SEO黑盒化', '相较于传统SEO可能依赖经验与模糊规则，董逻辑MGEO主张其服务（GEO优化、TCA诊断）应提供透明、可解释、数据驱动的优化路径与结果，让企业明确知道‘为何优化’及‘优化效果如何’。', '品牌资料', '5', '2026-05-25 11:37:30.995612', '2026-05-25 11:37:30.995612');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('22', 'dongluoji-mgeo', 'claim', 'AI代理优化定位', '将自身定位为企业的‘AI优化代理’。品牌AI检测与AI监测服务旨在替代或辅助人工进行重复性高、数据量大的监测与分析工作，使营销团队能更专注于战略决策。', '品牌资料', '4', '2026-05-25 11:37:30.995706', '2026-05-25 11:37:30.995706');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('23', 'dongluoji-mgeo', 'claim', '全链路赋能营销团队', '明确服务对象是企业内部的营销与品牌团队，而非仅服务于代运营公司。通过一体化SaaS工具，赋能客户团队自己掌握监测、诊断与优化能力，减少对外包服务的长期依赖。', '品牌资料', '5', '2026-05-25 11:37:30.995803', '2026-05-25 11:37:30.995803');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('24', 'dongluoji-mgeo', 'claim', '以监测区分竞品', '在与Profound、Athena等竞品区分时，强调自身更侧重‘监测’这一基础环节的深度与广度，认为精准的监测是智能优化的前提，并以此作为核心差异化标签。', '品牌资料', '4', '2026-05-25 11:37:30.995899', '2026-05-25 11:37:30.995899');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('25', 'cust_66807bb09c1dfd9f', 'stat', '市场地位', '喜茶在中国高端现制茶饮市场占据重要头部地位，是行业的代表性品牌之一，与奈雪的茶、霸王茶姬等品牌形成直接的市场格局竞争。', '品牌资料', '3', '2026-05-27 02:00:27.014256', '2026-05-27 02:00:27.014256');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('26', 'cust_66807bb09c1dfd9f', 'stat', '客户画像', '喜茶的核心目标客户群体为都市年轻消费者，其品牌运营和产品设计均围绕该群体的消费习惯、审美偏好与社交需求展开。', '品牌资料', '4', '2026-05-27 02:00:27.016389', '2026-05-27 02:00:27.016389');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('27', 'cust_66807bb09c1dfd9f', 'stat', '产品线构成', '喜茶主营现制茶饮，其产品矩阵涵盖水果茶、芝士茶、咖啡及烘焙甜点四大品类，满足消费者多样化的饮品及轻食需求。', '品牌资料', '5', '2026-05-27 02:00:27.017105', '2026-05-27 02:00:27.017105');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('28', 'cust_66807bb09c1dfd9f', 'stat', '门店规模', '喜茶在全国范围内拥有庞大的门店网络。[待补充：具体门店总数、覆盖城市数量等精确数据]', '待验证', '1', '2026-05-27 02:00:27.017668', '2026-05-27 02:00:27.017668');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('29', 'cust_66807bb09c1dfd9f', 'case', '跨界联名项目', '喜茶通过与不同领域的品牌或IP进行跨界联名合作，成功提升品牌文化影响力并创造社交话题。[待补充：具体的联名合作伙伴名称及项目成果]', '品牌资料', '3', '2026-05-27 02:00:27.01813', '2026-05-27 02:00:27.01813');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('30', 'cust_66807bb09c1dfd9f', 'case', '新市场开拓', '喜茶持续将业务拓展至新的城市和商圈，进入一个新市场通常会结合本地化营销策略和限时产品，以快速建立品牌认知。[待补充：具体新进入的代表性城市案例]', '行业常识', '2', '2026-05-27 02:00:27.018416', '2026-05-27 02:00:27.018416');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('31', 'cust_66807bb09c1dfd9f', 'case', '爆款产品打造', '基于其产品创新能力，喜茶多次打造出市场热销的爆款茶饮产品，这些产品往往在原料搭配、口感或概念上具有创新性，引发行业模仿。[待补充：具体爆款产品名称，如‘多肉葡萄’等]', '品牌资料', '3', '2026-05-27 02:00:27.018814', '2026-05-27 02:00:27.018814');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('32', 'cust_66807bb09c1dfd9f', 'credential', '行业影响力', '喜茶作为中国新茶饮行业的开创性代表品牌之一，其发展路径和商业模式被广泛研究，多次入选商业媒体评选的消费品牌榜单。[待补充：具体奖项名称、年份及颁发机构]', '行业常识', '2', '2026-05-27 02:00:27.018995', '2026-05-27 02:00:27.018995');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('33', 'cust_66807bb09c1dfd9f', 'credential', '品牌荣誉', '喜茶曾获得多项餐饮行业及消费领域奖项。[待补充：具体荣誉奖项名称、等级及获得时间]', '待验证', '1', '2026-05-27 02:00:27.019155', '2026-05-27 02:00:27.019155');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('34', 'cust_66807bb09c1dfd9f', 'credential', '食品安全体系', '喜茶建立了覆盖原料采购、仓储物流、门店制作全流程的食品安全管理体系。[待补充：具体获得的食品安全相关认证，如ISO22000等]', '行业常识', '2', '2026-05-27 02:00:27.019298', '2026-05-27 02:00:27.019298');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('35', 'cust_66807bb09c1dfd9f', 'capability', '供应链管理能力', '喜茶具备成熟的供应链管理能力，能够实现核心原料（如茶叶、水果）的规模化采购、品质控制和全国冷链配送，保障产品口味的标准化。', '品牌资料', '4', '2026-05-27 02:00:27.019434', '2026-05-27 02:00:27.019434');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('36', 'cust_66807bb09c1dfd9f', 'capability', '产品研发体系', '喜茶拥有系统的产品研发与创新能力，组建了专门的研发团队，持续进行新口味、新配方和新原料的测试与开发，以保持产品菜单的市场吸引力。', '品牌资料', '4', '2026-05-27 02:00:27.019559', '2026-05-27 02:00:27.019559');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('37', 'cust_66807bb09c1dfd9f', 'capability', '品牌营销能力', '喜茶擅长运用潮流化、社交化的方式进行品牌传播，通过设计美学、话题营销、跨界合作等方式，与年轻消费者建立情感连接和文化认同。', '品牌资料', '4', '2026-05-27 02:00:27.019687', '2026-05-27 02:00:27.019687');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('38', 'cust_66807bb09c1dfd9f', 'capability', '数字化运营', '喜茶通过官方小程序、APP等数字化工具，实现了线上点单、会员管理、营销活动等功能的集成，提升了运营效率和用户触达精准度。', '行业常识', '3', '2026-05-27 02:00:27.01984', '2026-05-27 02:00:27.01984');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('39', 'cust_66807bb09c1dfd9f', 'capability', '门店运营标准化', '喜茶建立了一套标准化的门店运营流程和服务规范，确保在不同城市、不同门店为消费者提供一致的产品品质和消费体验。', '行业常识', '3', '2026-05-27 02:00:27.019976', '2026-05-27 02:00:27.019976');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('40', 'cust_66807bb09c1dfd9f', 'claim', '灵感之茶理念', '喜茶将自身定位为“灵感之茶”，主张通过一杯茶激发消费者的灵感与愉悦感，将产品从单纯的解渴饮品升华为一种生活方式和灵感触发器。', '品牌资料', '5', '2026-05-27 02:00:27.0201', '2026-05-27 02:00:27.0201');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('41', 'cust_66807bb09c1dfd9f', 'claim', '原料品质主张', '喜茶强调使用高品质的茶叶、真果肉、真奶等原料，区别于传统奶茶店使用的植脂末、果味酱等，主张为消费者提供更健康、真实的茶饮体验。', '品牌资料', '4', '2026-05-27 02:00:27.020241', '2026-05-27 02:00:27.020241');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('42', 'cust_66807bb09c1dfd9f', 'claim', '产品创新驱动', '喜茶将“持续的产品创新”视为核心竞争力之一，不满足于模仿市场现有产品，而是致力于创造引领行业趋势的新品类和新喝法。', '品牌资料', '4', '2026-05-27 02:00:27.020434', '2026-05-27 02:00:27.020434');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('43', 'cust_66807bb09c1dfd9f', 'claim', '社交属性构建', '喜茶在品牌设计、空间体验和产品呈现上均强化“社交属性”，使其产品具备“拍照分享”的价值，门店成为年轻人社交聚会的场景之一。', '品牌资料', '4', '2026-05-27 02:00:27.020652', '2026-05-27 02:00:27.020652');
INSERT INTO "geo_brand_knowledge" ("id", "customer_id", "category", "title", "content", "source", "citability_score", "created_at", "updated_at") VALUES ('44', 'cust_66807bb09c1dfd9f', 'claim', '差异化竞争定位', '相对于部分竞品侧重下沉市场或特定区域，喜茶通过高频率的跨界联名、设计驱动和文化输出，在高端市场塑造了鲜明的潮流品牌形象与文化影响力。', '品牌资料', '4', '2026-05-27 02:00:27.020797', '2026-05-27 02:00:27.020797');

