INSERT INTO "automation_workflows" ("id", "workflow_id", "brand_name", "industry", "website", "services", "competitors", "positioning", "article_count", "status", "current_step", "customer_id", "keyword_library_id", "title_library_id", "knowledge_base_id", "task_id", "error_message", "created_at", "updated_at", "completed_at", "diagnosis_id") VALUES ('10', 'wf_20260527015716_32b15f21', '喜茶', '新茶饮 / 餐饮', 'heytea.com', '现制茶饮, 水果茶, 芝士茶, 咖啡, 烘焙甜点', '奈雪的茶, 茶百道, 古茗, 沪上阿姨, 霸王茶姬', '喜茶的品牌定位是以年轻消费者为核心，以“灵感之茶”为品牌理念，通过高品质原料、创新茶饮产品和潮流化传播，打造具有社交属性和生活方式感的新式茶饮品牌。', '10', 'completed', 'done', 'cust_66807bb09c1dfd9f', '10', '10', '8', '9', NULL, '2026-05-27 01:57:16.871105', '2026-05-27 02:13:14.104748', '2026-05-27 02:13:14', '30787c3f-2ba8-41ff-8f79-e6a6486dd2f3');

-- automation_workflow_steps (34 rows)
INSERT INTO "automation_workflow_steps" ("id", "workflow_id", "step_id", "step_order", "status", "started_at", "finished_at", "elapsed_seconds", "output_data", "error_message", "created_at", "updated_at") VALUES ('67', 'wf_20260524215341_168de591', 'collect', '1', 'completed', '2026-05-24 21:53:41.730308', '2026-05-24 21:53:56.165146', '14', '{"collected_info":"**董逻辑 MGEO**\n\n*   **主营业务**：董逻辑 MGEO 是一家专注于生成式引擎优化（GEO）领域的B2B SaaS服务商。其核心业务围绕企业在人工智能搜索与回答场景中的可见性与影响力展开，具体服务包括：对品牌在AI回答中的表现进行检测与诊断（品牌AI检测、TCA诊断），通过优化内容与数据策略提升AI提及率与正面性（GEO优化），并提供跨平台的内容分发与AI回答实时监测服务。\n*   **目标客户**：该品牌主要面向重视线上品牌声誉与数字营销效果的企业客户，特别是那些在激烈市场竞争中，需要确保其品牌信息在主流AI搜索与对话平台（如各类AI助手）中能被准确、积极呈现的中大型企业。目标行业可能包括消费品牌、科技公司、专业服务机构等。\n*   **核心优势**：其核心优势在于专注于“生成式AI搜索”这一新兴且快速演变的赛道，相较于传统SEO公司，它更专注于优化针对大语言模型的内容与数据。通过提供从监测、诊断到优化、分发的全链路工具，旨在帮助客户在由AI主导的信息分发环境中建立数据驱动的、可追踪的品牌影响力。其服务具有实时性和针对性强的特点，以应对AI回答动态更新的挑战。\n\n（注：以上信息基于官网披露的服务项目及行业通用知识推断而成，旨在提供客观概述。）","model_used":"demo-chat-model"}', '', '2026-05-24 21:53:41.415', '2026-05-24 21:53:56.165146');
INSERT INTO "automation_workflow_steps" ("id", "workflow_id", "step_id", "step_order", "status", "started_at", "finished_at", "elapsed_seconds", "output_data", "error_message", "created_at", "updated_at") VALUES ('68', 'wf_20260524215341_168de591', 'diagnosis', '2', 'completed', '2026-05-24 21:53:56.166725', '2026-05-24 21:53:56.20033', '0', '{"diagnosis_id":"4bd7ba44-2234-45bc-9f0d-ed54f25250ba","overall_score":49,"industry":"B2B SaaS","predicted_hit_rate":"low"}', '', '2026-05-24 21:53:41.41523', '2026-05-24 21:53:56.20033');
