INSERT INTO "automation_workflow_steps" ("id", "workflow_id", "step_id", "step_order", "status", "started_at", "finished_at", "elapsed_seconds", "output_data", "error_message", "created_at", "updated_at") VALUES ('77', 'wf_20260525113406_361c37a4', 'collect', '1', 'completed', '2026-05-25 11:34:06.549861', '2026-05-25 11:34:27.230694', '21', '{"collected_info":"董逻辑MGEO是一家B2B SaaS企业服务提供商，专注于GEO监测及相关优化领域。其主营业务包括基于AI的品牌检测、GEO（地理优化）优化、TCA诊断（推断为内容分析或相关评估）、内容分发和AI监测等SaaS工具。目标客户主要为企业，特别是市场营销、品牌管理及内容运营团队，旨在提升在线品牌可见性和优化数字营销效果。核心优势在于以GEO监测为核心定位，结合AI技术提供智能化的优化与监测服务，相较于传统SEO公司更侧重数据驱动和自动化解决方案。","model_used":"demo-chat-model"}', '', '2026-05-25 11:34:06.259877', '2026-05-25 11:34:27.230694');
